import React from "react";

export default function Policy() {
  return (
    <section className="bg-black text-white py-16 px-6 md:px-16">
      {/* Title */}
      <h1 className="text-center text-3xl font-extrabold text-[#8944F5] my-6">
        Privacy Policy & Terms
      </h1>

      {/* Scrollable Content */}
      <div className="max-w-6xl mx-auto bg-[#0c0c0c] rounded-2xl shadow-lg p-2 md:p-12 overflow-y-auto max-h-[75vh] custom-scroll">
        <p className="mb-2 leading-relaxed text-gray-300">
            I. INTRODUCTION TO AND ACCEPTANCE OF THE TERMS
Welcome and thank you for choosing Hago. This Terms of Service and User Agreement (this “Agreement”), which also includes and hereby incorporates the Privacy Policy(the “Privacy Policy”), is a legally binding agreement between HAGO Singapore PTE. LTD. (9 Straits View, Marina One West Tower, #05-07, Singapore 018937) (the “Company”, “we” or “us”) and you (“you”) governing your use of the Hago mobile application (the “App”, if any), the Hago client software (the “Software”, if any), the https://www.ihago.net website (the “Site”) and other related Internet services (collectively, the “Services”), as a registered user of the Services (“Registered User”). Unless you accept this Agreement, otherwise you have no right or authorization to use any part of the Services which requires you to be a Registered User. We may offer various products and services in addition to Hago. As long as you have signed up to be a registered user of any of them or Hago, you may access and use all such products and services through the same user credential. Should such additional products and services have their own terms of service or user agreements, you may have to further agree with such terms of service or user agreements before using such additional products and services. By checking the “I have read and agree to the Terms of Service and User Agreement” checkbox and completing the registration (sign-up) process, or continue to use or access any of the Services as a Registered User, you agree and represent to us: i) that you are at least 18 years of age, or the statutory age of majority in your state of nationality and residence, whichever is higher; ii) that you are not restricted from using the Services, by law, by contract, or by us; iii) that you fully agree with the terms and conditions set forth in this Agreement; iv) and where necessary, your legal guardian has reviewed and consented to this Agreement, and agreed to be responsible for any of your liability arising hereof.
        </p>
        <p className="mb-2 leading-relaxed text-gray-300"></p>
        <p className="mb-2 leading-relaxed text-gray-300"></p>
      </div>

      {/* Back to Top Button */}
      <button
        onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
        className="fixed bottom-6 right-6 bg-[#8944F5] hover:bg-[#7736d4] text-white px-4 py-2 rounded-full shadow-md hover:shadow-[#8944F5]/50 transition-all duration-300"
      >
        ↑ Top
      </button>
    </section>
  );
}
